def compute(vars):
    unpaid_principal_balance = vars["v1"]
    potential_maximum_exposure = vars["v2"]

    if unpaid_principal_balance == 0:
        return None

    ratio = potential_maximum_exposure / unpaid_principal_balance
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "unpaid_principal_balance": unpaid_principal_balance,
            "potential_maximum_exposure": potential_maximum_exposure,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
